head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.clickBzProcsNo = "";
scwin.clickListBzSeq = "";
scwin.vScrenID = "ULDSTF05002.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = $c.stf.getObjectValue(rdo_SECUGRP_ID);
    arrPar[3] = $c.stf.getObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD);
    arrPar[4] = SEARCH_TYP_SER;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetPar = function(arrPar) {
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
};
scwin.fn_GetParForIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISU_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = $c.stf.getObjectValue(rdo_SECUGRP_ID);
    arrPar[3] = $c.stf.getObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD);
    arrPar[4] = SEARCH_TYP_SER;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParForIsuCd = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_NM);
};
scwin.fn_set_code = function() {
    //상장주선인
    dts_SearchLeadComMbrNo.DataID = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listLeadCom&For=R";
    dts_SearchLeadComMbrNo.Reset();
    //alert("call");

};
scwin.fn_setBzProcsNo = function(obj) {
    scwin.clickBzProcsNo = dts_List.getCellData(eval(obj), "BZ_PROCS_NO");
    //alert("fn_setBzProcsNo():"+clickBzProcsNo);

};
scwin.fn_getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};
scwin.fn_setListBzSeq = function(obj) {
    scwin.clickListBzSeq = dts_List.getCellData(eval(obj), "LIST_BZ_SEQ");
    //alert("fn_setBzProcsNo():"+clickBzProcsNo);

};
scwin.fn_getBzProcsNo = function() {
    return scwin.clickListBzSeq;
};
scwin.fn_list_sync = function() {
    var url = "/KindStk.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listKindStkPreList&inputMessageId=KIND_STK_PREEXAM_SEARCH_OUT";
    url += "&SECUGRP_ID=" + $c.stf.getObjectValue(rdo_SECUGRP_ID);
    url += "&LIST_LM_CD_IDX=" + cmb_ListLMCd.getSelectedIndex();
    url += "&LIST_LM_CD=" + $c.stf.getObjectValue(cmb_ListLMCd);
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    url += "&LEADCOM_MBR_NO=" + $c.stf.getObjectValue(cmb_LeadcomMbrNo);
    url += "&DATE_TYPE=" + $c.stf.getObjectValue(rdo_DateType);
    url += "&S_DATE=" + $c.stf.getObjectValue(edt_SDate);
    url += "&E_DATE=" + $c.stf.getObjectValue(edt_EDate);
    url += "&SPOT_ISU_TRD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD);

    //alert("vListMdCd :"+vListMdCd); 
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_OpenDetail = async function(row) {
    var hight = "750";
    var yPoint = "30";
    var secugrpId;
    if (row > 0) {
        //그리드에서 선택시
        scwin.fn_setBzProcsNo(row);
        scwin.fn_setListBzSeq(row);
        secugrpId = dts_List.getCellData(row, 'SECUGRP_ID');
    } else {
        //신규버튼 선택시
        scwin.clickBzProcsNo = ""; //초기화
        scwin.clickListBzSeq = "";
        secugrpId = $c.stf.getObjectValue(cmb_NEW_SECUGRP_ID);
    }
    //alert("[secugrpId]"+secugrpId);
    if (secugrpId == SECUGRP_ID_DR || secugrpId == SECUGRP_ID_FS) {
        hight = "830";
        yPoint = "0";
    }
    //alert("[hight]"+hight);
    await $c.frame.CreateDialogFrame("KIKD_STK_DLG_PREEXAM", "/kindstk/ULDSTF05101.gfm", $c.lc.fn_getSecuGrpNm(secugrpId) + "  종류주식 예비심사관리", 100, yPoint, 1030, hight, "window");
};



/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, "예비심사리스트", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};



/*
 * 예비심사종목찾기 
 */
scwin.fn_PopFindKindStkExamIsu = async function() {
    await $c.frame.CreateDialogFrame("KIND_STK_PREEXAM_DLG_ISU_CD", "../kindstk/ULDSTF05107.gfm", "종류주식 예비심사 종목 선택", 10, 10, 430, 550 + 30, "window");
};
scwin.btn_CoCdSearch_onclick = function() {
    $c.lc.fn_PopFindExamCorp($c.stf.getObjectValue(rdo_SECUGRP_ID));
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_ExcelDown();
};
scwin.btn_New_onclick = function() {
    if ($c.stf.getObjectValue(cmb_NEW_SECUGRP_ID) == "") {
        $c.win.alert("신규등록할 [유가증권]을 선택하세요.");
        cmb_NEW_SECUGRP_ID.focus();
        return;
    } else {
        scwin.fn_OpenDetail(-999);
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.grd_List_OnDblClick = function(row, colid) {
    //if (colid=='COM_NM'){
    scwin.fn_OpenDetail(row);
    //}

};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.pre_newlisting.fn_initSearchDate(edt_SDate, edt_EDate);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    $c.cm.PanelToGroupBox(panel_Top);
    if (js_market == "1" || js_market == "2") {
        $c.cm.setColumnProp(grd_List, "TR_MKT_NM", "Show", false);
        $c.stf.setObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD, js_market);
        $c.stf.showObj(panel_mkt_gubun, false);
    } else {
        $c.stf.showObj(panel_mkt_gubun, true);
    }
    scwin.fn_set_code();
    scwin.fn_list_sync();
};
scwin.btn_ISU_CD_SEARCH_onclick = function() {
    scwin.fn_PopFindKindStkExamIsu();
};
